  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--text-primary);
  text-decoration: none;
  text-transform: uppercase;
}

nav[aria-label="Primary"] ul {
  display: flex;
  list-style: none;
  gap: 2rem;
}

